import React, { useEffect, useState } from "react";
import "./App.css";

function App() {
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({
    id: "",
    name: "",
    description: "",
    price: "",
    quantity: "",
  });

  // Fetch all products from FastAPI
  const loadProducts = async () => {
    const res = await fetch("http://127.0.0.1:8000/products");
    const data = await res.json();
    setProducts(data);
  };

  useEffect(() => {
    loadProducts();
  }, []);

  // Handle form changes
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // Add product
  const addProduct = async () => {
    await fetch("http://127.0.0.1:8000/products", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    loadProducts();
  };

  // Delete product
  const deleteProduct = async (id) => {
    await fetch(`http://127.0.0.1:8000/products/${id}`, {
      method: "DELETE",
    });
    loadProducts();
  };

  return (
    <div className="container">

      <h1 className="title">Telusko Trac</h1>

      <div className="card">
        <h2>Total: {products.length}</h2>
      </div>

      <div className="card">
        <h2>Add Product</h2>

        <input name="id" placeholder="ID" onChange={handleChange} />
        <input name="name" placeholder="Name" onChange={handleChange} />
        <input
          name="description"
          placeholder="Description"
          onChange={handleChange}
        />
        <input name="price" placeholder="Price" onChange={handleChange} />
        <input
          name="quantity"
          placeholder="Quantity"
          onChange={handleChange}
        />

        <button className="btn-add" onClick={addProduct}>
          Add
        </button>
      </div>

      <div className="card">
        <h2>Products</h2>

        <table className="products-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Description</th>
              <th>Price</th>
              <th>Quantity</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {products.map((p) => (
              <tr key={p.id}>
                <td>{p.id}</td>
                <td>{p.name}</td>
                <td>{p.description}</td>
                <td>${p.price}</td>
                <td>{p.quantity}</td>
                <td>
                  <button className="btn-edit">Edit</button>
                  <button
                    className="btn-delete"
                    onClick={() => deleteProduct(p.id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default App;
